window.kbPageData["views/entry/k-259e0b87a97a8b62"] = {"key":"entry/k-259e0b87a97a8b62","state":{"route":"entry/k-259e0b87a97a8b62"},"node":{"id":"k-259e0b87a97a8b62","mode":"k","title":"党性党风党纪一起抓","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#85"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["party"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"推进党风廉政建设要把党性教育、作风建设和纪律建设一同抓好，推动正风、肃纪、反腐相贯通。","review":{"definition":"推进党风廉政建设要把党性教育、作风建设和纪律建设一同抓好，推动正风、肃纪、反腐相贯通。","explanation":"2025年3月习近平在贵州考察时，把这项要求同持续铲除腐败滋生的土壤和条件联系起来。B项保留了「正风肃纪反腐相贯通」，却把「党性党风党纪」改成「党规党纪党务」，因此是本题要求选出的不准确表述。","references":[],"evidence":"党性党风党纪一起抓、正风肃纪反腐相贯通","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"73010ca4730714f9","label":"党性党风党纪一起抓","topic":"党政制度与理论","category":"非时政","text":"1.党性党风党纪一起抓\n党性：是政党固有的本质特征，是党员干部立身、立业、立言、立德的基石，\n是净化党风、严明党纪的内在依据。\n党风：是党在思想、政治、组织、工作、生活等各方面表现出来的态度和行为，\n是党性、党纪的外在体现，关系人心向背，关系党的生死存亡。\n党纪：是管党治党的戒尺，也是党员、干部约束自身行为的标准和遵循。\n党性、党风、党纪是有机整体，党性是根本，党风是表现，党纪是保障。党性、\n党风、党纪的内在一致性，决定了三者必须“一起抓”才能达到治病强身、固本培\n元的整体效果。","source":{"doc":"41195a191a57c1c36332","first":17,"last":17,"page":17,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#85":{"paper":"政治理论必刷100题","n":85,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",26],"asrc":["国省考政治理论必刷100题.pdf",87],"card":"d39717a3c184d8d0d152bf26","links":[{"id":"k-259e0b87a97a8b62","role":"直接考查","why":"准确识别一起抓的三个方面即可定位用语错误。"}]}},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-259e0b87a97a8b62":[["政治理论必刷100题#85"]]}};
